await page.goto('https://www.giallozafferano.it/');
const names=["Tiramisù","Panna cotta","Risotto alla milanese","Gnocchi di patate"];
const out={};
for(const n of names){
await page.goto('https://www.giallozafferano.it/ricerca-ricette/'+encodeURIComponent(n)+'/');
const links=await page.$$eval('article a[href*="/ricette/"], .gz-title a',as=>as.slice(0,3).map(a=>a.href+' | '+a.textContent.trim()));
out[n]=links;}
return out;

const urls=["Tiramisu","Panna-cotta","Risotto-alla-milanese","Gnocchi-di-patate"];
const out={};
for(const u of urls){
await page.goto('https://ricette.giallozafferano.it/'+u+'.html');
out[u]=await page.evaluate(()=>[document.title,...[...document.querySelectorAll('.gz-name-featured-data')].map(e=>e.textContent.replace(/\s+/g,' ').trim())]);}
return out;
